(17, 17, 'category', 'Khám phá thủ phủ miền Tây với chợ nổi Cái Răng tấp nập, vườn trái cây Mỹ Khánh và trải nghiệm văn hóa sông nước độc đáo.', 0, 0),
(18, 18, 'category', 'Trải nghiệm mùa nước nổi Rừng tràm Trà Sư, làng hoa Sa Đéc rực rỡ và những cánh đồng sen Tháp Mười bạt ngàn.', 0, 0),
(19, 19, 'category', 'Hành trình về xứ dừa Bến Tre, chèo xuồng ba lá len lỏi rạch dừa nước và thưởng thức trái cây chín cây tại cù lao Thới Sơn.', 0, 0),
(20, 20, 'category', 'Chinh phục Đất Mũi Cà Mau tận cùng Tổ quốc, tham quan rừng ngập mặn và khám phá nhà Công tử Bạc Liêu nức tiếng.', 0, 0),
(21, 21, 'category', 'Trải nghiệm du lịch sinh thái miệt vườn cù lao An Bình, homestay nhà vườn và đờn ca tài tử Nam Bộ mộc mạc.', 0, 0),
